        ('L01', 2024, 'LINGUAGENS', 'Língua Portuguesa', 'Variação Linguística', $text$Uma feira cultural reúne expressões usadas por moradores de diferentes regiões do Brasil. Uma visitante estranha uma palavra local e diz que ela está “errada” por não aparecer em seu vocabulário. Considerando a diversidade linguística brasileira, qual avaliação é mais adequada?$text$, $text$A variação lexical é parte do uso social da língua e pode marcar pertencimento cultural; diferença em relação ao repertório de alguém não significa erro.$text$, 'D', $text$Toda palavra regional deve ser eliminada da fala pública.$text$, $text$Uma variedade regional só é válida se estiver em dicionários antigos.$text$, $text$O vocabulário da visitante é o único padrão legítimo de comunicação.$text$, $text$A expressão local pode ser legítima em sua comunidade e revelar identidade cultural.$text$, $text$Variações regionais impedem qualquer compreensão entre brasileiros.$text$),
        ('L02', 2024, 'LINGUAGENS', 'Língua Portuguesa', 'Gêneros Textuais', $text$Uma reportagem apresenta, em parágrafos curtos, a infância, as mudanças de modalidade e as conquistas de três atletas paralímpicas. Qual é a finalidade principal desse conjunto de minibiógrafias?$text$, $text$A minibiógrafia seleciona acontecimentos marcantes da vida de uma pessoa para apresentar sua trajetória.$text$, 'B', $text$Ensinar as regras técnicas de todas as modalidades citadas.$text$, $text$Apresentar trajetórias pessoais e esportivas das atletas.$text$, $text$Divulgar a programação da próxima competição.$text$, $text$Comparar estatisticamente todas as atletas do país.$text$, $text$Substituir uma entrevista coletiva sobre esporte.$text$),
        ('L03', 2024, 'LINGUAGENS', 'Artes', 'Música', $text$Um instrumento de cordas levado de um país a outro passa a ser produzido com tamanho diferente e integrado a novos ritmos locais. O caso demonstra que uma prática musical pode$text$, $text$Circulações culturais permitem adaptação de objetos e práticas a novos contextos, sem exigir cópia idêntica da forma original.$text$, 'C', $text$manter obrigatoriamente a mesma forma e o mesmo uso em todos os lugares.$text$, $text$perder seu caráter cultural ao atravessar fronteiras.$text$, $text$ser apropriada e transformada por diferentes comunidades.$text$, $text$existir apenas onde o instrumento foi inventado.$text$, $text$dispensar a participação de músicos para adquirir novos sentidos.$text$),
        ('L04', 2024, 'LINGUAGENS', 'Língua Portuguesa', 'Interpretação de Texto', $text$Uma notícia sobre prevenção de doenças explica sintomas aos quais a população deve prestar atenção e orienta a procurar atendimento profissional quando eles aparecem. Qual função predomina nessas informações?$text$, $text$Ao descrever sinais e orientar a busca de atendimento, a notícia exerce função informativa e preventiva, sem fazer diagnóstico individual.$text$, 'A', $text$Alertar o leitor sobre sinais que exigem atenção.$text$, $text$Garantir um diagnóstico sem consulta médica.$text$, $text$Substituir exames laboratoriais por opinião pessoal.$text$, $text$Provar que campanhas de prevenção são desnecessárias.$text$, $text$Apresentar uma narrativa fictícia sem finalidade informativa.$text$),
        ('L05', 2024, 'LINGUAGENS', 'Literatura', 'Interpretação de Textos Literários', $text$Um texto descreve o preparo de um prato em versos, com ritmo, imagens expressivas e comentários afetivos do eu lírico. Embora também contenha instruções culinárias, qual elemento sustenta sua leitura como poema?$text$, $text$A linguagem figurada, o ritmo e a organização em versos produzem efeito estético próprio do texto poético.$text$, 'E', $text$A existência de ingredientes mensuráveis.$text$, $text$A ordem obrigatória de cada etapa da receita.$text$, $text$A indicação de tempo de cozimento.$text$, $text$A presença de um destinatário para as instruções.$text$, $text$O trabalho expressivo com a linguagem e a forma em versos.$text$),
        ('L06', 2025, 'LINGUAGENS', 'Língua Portuguesa', 'Gêneros Textuais', $text$Ao encontrar um bilhete antigo, uma narradora relembra uma conversa familiar e reflete sobre como as pessoas mantêm laços apesar da distância. O que aproxima esse texto do gênero crônica?$text$, $text$A crônica frequentemente parte de um acontecimento cotidiano para construir uma observação subjetiva ou reflexiva.$text$, 'B', $text$A enumeração impessoal de normas de correspondência.$text$, $text$A reflexão a partir de uma situação comum da vida pessoal.$text$, $text$A apresentação de dados científicos sobre memória.$text$, $text$A exposição completa da história de uma família.$text$, $text$A defesa de uma tese por meio de estatísticas oficiais.$text$),
        ('L07', 2025, 'LINGUAGENS', 'Tecnologias da Informação e Comunicação', 'Cultura Digital', $text$Uma escola passou a receber trabalhos por plataforma digital, mas continua a usar bilhetes manuscritos em algumas atividades. O exemplo mostra que a expansão das tecnologias digitais$text$, $text$Novos suportes de escrita podem coexistir com práticas anteriores, atendendo a propósitos e contextos diferentes.$text$, 'C', $text$torna ilegal a escrita à mão.$text$, $text$elimina imediatamente os suportes anteriores.$text$, $text$pode conviver com práticas de escrita já existentes.$text$, $text$impede qualquer comunicação fora da internet.$text$, $text$exige que todo texto tenha a mesma aparência visual.$text$),
        ('L08', 2025, 'LINGUAGENS', 'Língua Portuguesa', 'Funções da Linguagem', $text$Em um bilhete lê-se: “Por favor, deixe a janela fechada antes de sair.” A linguagem está orientada principalmente para$text$, $text$O pedido dirige-se ao interlocutor e busca influenciar seu comportamento, caracterizando a função conativa ou apelativa.$text$, 'A', $text$induzir uma ação do destinatário.$text$, $text$descrever objetivamente a arquitetura do prédio.$text$, $text$falar sobre o próprio código linguístico.$text$, $text$criar um efeito poético pelo ritmo dos sons.$text$, $text$expressar apenas uma lembrança do remetente.$text$),
        ('L09', 2025, 'LINGUAGENS', 'Língua Portuguesa', 'Variação Linguística', $text$Em uma entrevista, uma estudante diz que se sente desvalorizada quando colegas ridicularizam o modo como sua família pronuncia certas palavras. Essa situação evidencia que o preconceito linguístico pode atingir$text$, $text$A maneira de falar está ligada à história e ao pertencimento do sujeito; depreciá-la também desvaloriza o grupo social associado.$text$, 'D', $text$apenas a escrita de documentos oficiais.$text$, $text$somente a velocidade da comunicação.$text$, $text$exclusivamente o ensino de línguas estrangeiras.$text$, $text$a identidade social de quem usa uma variedade da língua.$text$, $text$a estrutura física dos meios de comunicação.$text$),
        ('L10', 2025, 'LINGUAGENS', 'Língua Portuguesa', 'Coesão e Coerência', $text$Um artigo descreve cartas, mensagens instantâneas e chamadas de vídeo. Ao final, conclui: “Essas formas de contato não se substituem por completo; cada uma atende a necessidades distintas.” Qual papel a frase final desempenha no texto?$text$, $text$A conclusão reúne os exemplos sob a ideia de coexistência e adequação dos meios a situações diversas.$text$, 'E', $text$Introduz um assunto sem relação com o restante.$text$, $text$Apresenta uma contradição que torna o texto incoerente.$text$, $text$Repete literalmente todos os exemplos anteriores.$text$, $text$Apaga as diferenças entre os meios de comunicação.$text$, $text$Sintetiza a ideia central construída pelos exemplos.$text$),
        ('H01', 2024, 'CIENCIAS_HUMANAS', 'Geografia', 'Relevo', $text$Uma região próxima ao encontro de duas placas tectônicas registra terremotos mais intensos que outra localizada no interior de uma placa. Qual processo explica essa diferença?$text$, $text$O movimento relativo das placas concentra tensões em suas bordas; a liberação dessas tensões pode gerar terremotos.$text$, 'C', $text$A formação de nuvens sobre o oceano.$text$, $text$A erosão causada exclusivamente pelos rios.$text$, $text$O acúmulo e a liberação de energia nas bordas das placas.$text$, $text$A variação diária da temperatura do ar.$text$, $text$A alternância entre estações chuvosas e secas.$text$),
        ('H02', 2024, 'CIENCIAS_HUMANAS', 'Geografia', 'Questões Ambientais', $text$Depois do rompimento de uma barragem, uma comunidade precisou abandonar casas, escola e lugares de encontro. Mesmo moradores sem perda material relatam sofrimento ao não poder retornar. Que dimensão do impacto aparece nesse relato?$text$, $text$O espaço vivido inclui memórias e relações; perder acesso a ele também afeta pertencimento e vínculos sociais.$text$, 'B', $text$A ampliação da oferta de empregos locais.$text$, $text$O enfraquecimento dos vínculos afetivos com o lugar.$text$, $text$A eliminação de conflitos sobre o território.$text$, $text$O aumento automático da segurança ambiental.$text$, $text$A recuperação imediata do patrimônio cultural.$text$),
        ('H03', 2024, 'CIENCIAS_HUMANAS', 'História', 'Brasil Império', $text$No século XIX, comerciantes percorriam rios amazônicos em embarcações e negociavam com comunidades indígenas, quilombolas e pequenos produtores. Além da circulação de mercadorias, essa atividade favorecia$text$, $text$As rotas de comércio também aproximavam grupos e criavam relações sociais entre localidades distantes.$text$, 'D', $text$o isolamento permanente de todos os povoados.$text$, $text$o desaparecimento da navegação fluvial.$text$, $text$a substituição imediata de todos os mercados urbanos.$text$, $text$a formação de redes de contato e sociabilidade no interior.$text$, $text$o fim das diferenças culturais entre os grupos envolvidos.$text$),
        ('H04', 2024, 'CIENCIAS_HUMANAS', 'Sociologia', 'Movimentos Sociais', $text$Familiares de pessoas desaparecidas durante uma ditadura passam a se reunir em praça pública, de forma contínua, para exigir informações do Estado. A ação coletiva procura tornar visível principalmente$text$, $text$Ao reivindicar respostas sobre desaparecimentos, o movimento denuncia a repressão estatal e exige memória, verdade e justiça.$text$, 'A', $text$a violação de direitos humanos praticada ou encoberta pelo poder público.$text$, $text$uma disputa comercial entre diferentes empresas.$text$, $text$o interesse em substituir eleições por sorteios.$text$, $text$uma campanha para diminuir a participação popular.$text$, $text$o abandono de todas as reivindicações políticas.$text$),
        ('H05', 2024, 'CIENCIAS_HUMANAS', 'História', 'Primeira República', $text$Na passagem do século XIX para o XX, autoridades associaram ferrovias, iluminação elétrica e novos meios de comunicação à imagem de um país moderno. Na propaganda política da época, essa associação servia para$text$, $text$A modernização material foi usada como linguagem política para legitimar uma imagem progressista do novo regime.$text$, 'E', $text$defender o retorno do absolutismo monárquico.$text$, $text$negar a existência de mudanças técnicas.$text$, $text$impedir investimentos em infraestrutura.$text$, $text$demonstrar que a industrialização já alcançara igualmente todo o território.$text$, $text$apresentar a República como símbolo de progresso nacional.$text$),
        ('H06', 2025, 'CIENCIAS_HUMANAS', 'História', 'Primeira Guerra Mundial', $text$Durante uma guerra, países beligerantes censuram notícias sobre uma epidemia, enquanto a imprensa de um país neutro publica mais relatos. A doença acaba recebendo o nome associado ao país neutro, embora não tenha surgido ali. O caso mostra a influência da$text$, $text$A censura em alguns países e a divulgação em outro podem distorcer a percepção pública sobre a origem de um acontecimento.$text$, 'B', $text$composição química dos medicamentos sobre os jornais.$text$, $text$desigualdade na circulação pública de informações.$text$, $text$localização dos hospitais no interior das cidades.$text$, $text$mudança de idioma entre os profissionais de saúde.$text$, $text$redução do transporte marítimo no período.$text$),
        ('H07', 2025, 'CIENCIAS_HUMANAS', 'Geografia', 'População e Demografia', $text$Uma pesquisa anuncia “saída em massa das metrópoles”, mas seus dados mostram principalmente famílias de alta renda comprando uma segunda casa em municípios próximos, mantendo emprego na cidade grande. A generalização é inadequada porque o movimento observado é$text$, $text$O fenômeno descrito depende de renda e condições de trabalho que não representam a população urbana como um todo.$text$, 'C', $text$idêntico para todos os grupos sociais.$text$, $text$prova da extinção das metrópoles.$text$, $text$restrito a uma parcela com condições econômicas específicas.$text$, $text$causado exclusivamente pela mecanização agrícola.$text$, $text$necessariamente permanente para toda a população.$text$),
        ('H08', 2025, 'CIENCIAS_HUMANAS', 'Sociologia', 'Poder e Política', $text$Em escolas, fábricas e quartéis, horários, registros e avaliações passam a organizar a conduta cotidiana. O exemplo sugere que o exercício do poder pode ocorrer por meio da$text$, $text$O controle não depende só de grandes punições; ele também opera em práticas rotineiras e distribuídas por instituições.$text$, 'D', $text$ausência completa de regras institucionais.$text$, $text$destruição das relações de trabalho.$text$, $text$aplicação exclusiva de punições públicas espetaculares.$text$, $text$difusão de mecanismos de vigilância e disciplina.$text$, $text$eliminação de todas as diferenças entre instituições.$text$),
        ('H09', 2025, 'CIENCIAS_HUMANAS', 'Geografia', 'Globalização', $text$Uma estiagem prolongada reduz a profundidade de um rio usado para levar matérias-primas às fábricas. Navios precisam transportar menos carga por viagem. Qual consequência econômica imediata é mais provável?$text$, $text$Com menor carga por viagem, são necessárias mais viagens ou rotas alternativas para transportar o mesmo volume.$text$, 'A', $text$Aumento do custo logístico por unidade transportada.$text$, $text$Desaparecimento de todas as atividades industriais.$text$, $text$Crescimento automático da capacidade de cada embarcação.$text$, $text$Redução obrigatória dos preços de todos os produtos.$text$, $text$Fim da necessidade de outras rotas de transporte.$text$),
        ('H10', 2025, 'CIENCIAS_HUMANAS', 'Geografia', 'Urbanização', $text$Fotografias da mesma orla, feitas com vinte anos de intervalo, mostram que casas baixas deram lugar a edifícios residenciais de muitos andares. Qual transformação da paisagem é evidenciada?$text$, $text$A substituição de construções baixas por edifícios altos caracteriza a verticalização urbana.$text$, 'E', $text$Ruralização da faixa litorânea.$text$, $text$Desaparecimento da ocupação humana.$text$, $text$Formação de um deserto climático.$text$, $text$Retorno integral à arquitetura original.$text$, $text$Intensificação da verticalização do espaço urbano.$text$),
        ('N01', 2024, 'CIENCIAS_DA_NATUREZA', 'Física', 'Eletricidade', $text$Um LED deve receber 3 V e operar com corrente de 0,02 A. Para ligá-lo em série a uma fonte ideal de 9 V, qual resistência deve ter o resistor de proteção? Considere desprezíveis as demais resistências.$text$, $text$O resistor deve receber 9 − 3 = 6 V. Pela lei de Ohm, R = 6/0,02 = 300 Ω.$text$, 'C', $text$150 Ω.$text$, $text$200 Ω.$text$, $text$300 Ω.$text$, $text$450 Ω.$text$, $text$600 Ω.$text$),
        ('N02', 2024, 'CIENCIAS_DA_NATUREZA', 'Química', 'Estequiometria', $text$Uma amostra de 100 L de biogás contém 70% de metano em volume. Nas condições da amostra, 1 mol de gás ocupa 25 L. Sabendo que a massa molar do metano é 16 g/mol, qual é a massa de metano presente?$text$, $text$Há 70 L de metano, correspondentes a 70/25 = 2,8 mol. A massa é 2,8 × 16 = 44,8 g.$text$, 'B', $text$16,0 g.$text$, $text$44,8 g.$text$, $text$70,0 g.$text$, $text$112,0 g.$text$, $text$160,0 g.$text$),
        ('N03', 2024, 'CIENCIAS_DA_NATUREZA', 'Biologia', 'Microbiologia', $text$Uma vacina induz resposta imune contra proteínas da superfície de um vírus. Meses depois, uma nova linhagem apresenta alterações nessas proteínas e consegue infectar parte dos indivíduos vacinados. Qual processo ajuda a explicar a redução da proteção?$text$, $text$Alterações em proteínas virais podem modificar os antígenos e reduzir o reconhecimento por anticorpos induzidos anteriormente.$text$, 'D', $text$Desaparecimento de todas as células de defesa humanas.$text$, $text$Conversão do vírus em bactéria.$text$, $text$Interrupção da produção de proteínas pelo organismo humano.$text$, $text$Mudança dos antígenos reconhecidos pela resposta imune.$text$, $text$Transformação da vacina em antibiótico.$text$),
        ('N04', 2024, 'CIENCIAS_DA_NATUREZA', 'Biologia', 'Ecologia', $text$Uma escola coleta embalagens plásticas limpas e as encaminha a uma cooperativa que as transforma em matéria-prima para novos objetos. Qual é o principal benefício ambiental dessa medida, em comparação com o descarte inadequado?$text$, $text$A reciclagem mantém parte do material em circulação e pode diminuir o uso de matéria-prima virgem.$text$, 'E', $text$Garantir que nenhum plástico será produzido no futuro.$text$, $text$Converter automaticamente todo plástico em adubo.$text$, $text$Eliminar a necessidade de coleta e separação.$text$, $text$Fazer o plástico desaparecer sem processamento.$text$, $text$Reaproveitar material e reduzir a demanda por matéria-prima nova.$text$),
        ('N05', 2024, 'CIENCIAS_DA_NATUREZA', 'Biologia', 'Evolução', $text$Em grandes altitudes, a pressão parcial de oxigênio no ar é menor. Uma variante de hemoglobina que se liga ao oxigênio com maior facilidade pode beneficiar animais desse ambiente porque favorece a$text$, $text$Maior afinidade da hemoglobina pode facilitar a ligação ao oxigênio em condições de baixa pressão parcial desse gás.$text$, 'A', $text$captação de oxigênio mesmo quando ele está menos disponível.$text$, $text$produção de oxigênio pelo sangue.$text$, $text$eliminação completa do gás carbônico nos músculos.$text$, $text$substituição dos pulmões por vasos sanguíneos.$text$, $text$transformação do oxigênio em glicose no plasma.$text$),
        ('N06', 2025, 'CIENCIAS_DA_NATUREZA', 'Biologia', 'Ecologia', $text$Uma espécie animal introduzida em determinada região encontra poucos predadores naturais e passa a consumir alimento usado por espécies nativas. Qual impacto ecológico é esperado se sua população crescer sem controle?$text$, $text$Espécies invasoras podem disputar recursos com organismos nativos e alterar o equilíbrio das comunidades biológicas.$text$, 'C', $text$Extinção imediata de todos os microrganismos.$text$, $text$Aumento obrigatório da diversidade em todos os habitats.$text$, $text$Intensificação da competição por recursos com espécies locais.$text$, $text$Fim das cadeias alimentares da região.$text$, $text$Redução garantida de toda atividade humana.$text$),
        ('N07', 2025, 'CIENCIAS_DA_NATUREZA', 'Química', 'Reações Químicas', $text$Pedaços de maçã escurecem após serem cortados devido a reações de oxidação favorecidas por enzimas. Adicionar suco de limão costuma retardar esse efeito. Qual propriedade do limão contribui para isso?$text$, $text$O suco de limão reduz o pH; condições mais ácidas dificultam a ação das enzimas relacionadas ao escurecimento.$text$, 'B', $text$Aumentar o pH até valores fortemente básicos.$text$, $text$Tornar o meio mais ácido, reduzindo a atividade das enzimas envolvidas.$text$, $text$Remover fisicamente todo o oxigênio do ambiente.$text$, $text$Converter as enzimas em moléculas de açúcar.$text$, $text$Aumentar a temperatura da fruta.$text$),
        ('N08', 2025, 'CIENCIAS_DA_NATUREZA', 'Química', 'Ligações Químicas', $text$Uma peça metálica de aspecto uniforme é analisada e apresenta cobre e zinco misturados em sua composição. Como esse material é classificado?$text$, $text$A combinação de metais como cobre e zinco forma uma liga metálica, caso do latão.$text$, 'A', $text$Liga metálica.$text$, $text$Sal iônico puro.$text$, $text$Emulsão de dois líquidos.$text$, $text$Gás monoatômico.$text$, $text$Molécula de água.$text$),
        ('N09', 2025, 'CIENCIAS_DA_NATUREZA', 'Química', 'Reações Químicas', $text$Considere o equilíbrio gasoso CHCl₃ + Cl₂ ⇌ CCl₄ + HCl. Mantidas as demais condições, qual intervenção desloca o equilíbrio no sentido de maior formação de CCl₄?$text$, $text$Ao acrescentar um reagente, o sistema tende a consumi-lo, favorecendo o sentido de formação dos produtos. Catalisadores não deslocam a posição do equilíbrio.$text$, 'D', $text$Retirar CHCl₃ do recipiente.$text$, $text$Adicionar HCl ao recipiente.$text$, $text$Adicionar um catalisador, sem alterar as quantidades das substâncias.$text$, $text$Adicionar CHCl₃ ao recipiente.$text$, $text$Retirar Cl₂ do recipiente.$text$),
        ('N10', 2025, 'CIENCIAS_DA_NATUREZA', 'Física', 'Eletricidade', $text$Uma bomba elétrica funciona com tensão entre 95 V e 105 V. Cada placa fotovoltaica idêntica fornece 34 V em operação. Se as placas forem ligadas em série, qual é o menor número que atende à faixa de tensão da bomba?$text$, $text$Tensões em série somam-se: 3 × 34 = 102 V, dentro da faixa. Uma ou duas placas não alcançam 95 V.$text$, 'E', $text$Uma placa, com 34 V.$text$, $text$Duas placas, com 68 V.$text$, $text$Duas placas, com 102 V.$text$, $text$Quatro placas, com 102 V.$text$, $text$Três placas, com 102 V.$text$),
        ('M01', 2024, 'MATEMATICA', 'Matemática', 'Progressões', $text$Uma estudante começa uma mensagem com 4 símbolos. Em cada etapa seguinte, copia todo o conteúdo da etapa anterior e cola ao lado, duplicando a quantidade. Quantos símbolos haverá ao final da sexta etapa, contando a primeira como a etapa dos 4 símbolos?$text$, $text$Da primeira à sexta etapa ocorrem cinco duplicações: 4 × 2⁵ = 128.$text$, 'C', $text$64.$text$, $text$96.$text$, $text$128.$text$, $text$256.$text$, $text$512.$text$),
        ('M02', 2024, 'MATEMATICA', 'Matemática', 'Geometria Espacial', $text$Um trapézio retângulo possui duas bases paralelas de comprimentos diferentes. Ele gira completamente em torno do lado perpendicular às bases. Qual sólido é formado?$text$, $text$As bases do trapézio geram círculos de raios diferentes e o lado inclinado gera a superfície lateral de um tronco de cone.$text$, 'D', $text$Esfera.$text$, $text$Cilindro.$text$, $text$Pirâmide.$text$, $text$Tronco de cone.$text$, $text$Cone de base dupla.$text$),
        ('M03', 2024, 'MATEMATICA', 'Matemática', 'Geometria Plana', $text$Um campo retangular media 105 m por 68 m. Após uma reforma, passou a medir 100 m por 64 m. De quantos metros quadrados foi a redução da área?$text$, $text$A área inicial era 105 × 68 = 7 140 m²; a final é 100 × 64 = 6 400 m². Diferença: 740 m².$text$, 'C', $text$360 m².$text$, $text$640 m².$text$, $text$740 m².$text$, $text$840 m².$text$, $text$1 140 m².$text$),
        ('M04', 2024, 'MATEMATICA', 'Matemática', 'Equações', $text$Um evento custa R$ 2 500,00 para ser organizado, além de R$ 10,00 por participante. Cada ingresso custa R$ 40,00. Qual é o menor número inteiro de ingressos que precisa ser vendido para que a arrecadação cubra os custos?$text$, $text$Para n participantes, 40n ≥ 2 500 + 10n, logo 30n ≥ 2 500 e n ≥ 83,33... O mínimo inteiro é 84.$text$, 'C', $text$80.$text$, $text$83.$text$, $text$84.$text$, $text$90.$text$, $text$100.$text$),
        ('M05', 2024, 'MATEMATICA', 'Matemática', 'Probabilidade', $text$Uma caixa contém 3 cartões vermelhos e 2 azuis. Dois cartões são retirados sem reposição. Qual é a probabilidade de sair um de cada cor, em qualquer ordem?$text$, $text$Entre as 10 duplas possíveis, 3 × 2 = 6 têm cores diferentes. Assim, 6/10 = 3/5.$text$, 'C', $text$1/5.$text$, $text$2/5.$text$, $text$3/5.$text$, $text$4/5.$text$, $text$1.$text$),
        ('M06', 2025, 'MATEMATICA', 'Matemática', 'Matemática Básica', $text$Uma cantina compara o sódio total de cinco embalagens. O produto A tem 4 porções de 140 mg; B, 3 de 180 mg; C, 5 de 110 mg; D, 2 de 260 mg; e E, 6 de 90 mg. Qual embalagem contém menos sódio no total?$text$, $text$Os totais são 560, 540, 550, 520 e 540 mg. O menor é 520 mg, do produto D.$text$, 'D', $text$Produto A.$text$, $text$Produto B.$text$, $text$Produto C.$text$, $text$Produto D.$text$, $text$Produto E.$text$),
        ('M07', 2025, 'MATEMATICA', 'Matemática', 'Funções', $text$Durante uma atividade de relaxamento, a frequência respiratória permanece em 18 incursões por minuto no início, diminui gradualmente até 12 e, depois, mantém-se em 12. Qual descrição corresponde a esse comportamento ao longo do tempo?$text$, $text$O enunciado indica um trecho inicial estável, uma redução e um trecho final estável no novo valor.$text$, 'A', $text$Primeiro constante, depois decrescente e por fim constante.$text$, $text$Crescente em todo o intervalo.$text$, $text$Decrescente em todo o intervalo, sem estabilização.$text$, $text$Constante em 18 durante todo o período.$text$, $text$Primeiro crescente e depois decrescente.$text$),
        ('M08', 2025, 'MATEMATICA', 'Matemática', 'Geometria Plana', $text$Uma área circular de proteção, inicialmente com raio de 20 km, terá o raio ampliado para 30 km. Usando π = 3, em quantos quilômetros quadrados a área aumentará?$text$, $text$A diferença é π(30² − 20²) = 3(900 − 400) = 1 500 km².$text$, 'D', $text$300 km².$text$, $text$600 km².$text$, $text$900 km².$text$, $text$1 500 km².$text$, $text$2 700 km².$text$),
        ('M09', 2025, 'MATEMATICA', 'Matemática', 'Funções', $text$Uma companhia cobra R$ 40,00 por mês para consumo de até 5 m³ de água. Acima disso, acrescenta R$ 12,00 por metro cúbico excedente. Quanto paga uma residência que consumiu 11 m³ no mês?$text$, $text$O excedente é 11 − 5 = 6 m³. Total: 40 + 6 × 12 = R$ 112,00.$text$, 'E', $text$R$ 72,00.$text$, $text$R$ 84,00.$text$, $text$R$ 100,00.$text$, $text$R$ 108,00.$text$, $text$R$ 112,00.$text$),
        ('M10', 2025, 'MATEMATICA', 'Matemática', 'Razão e Proporção', $text$O plano X oferece 80 Mbps por R$ 80,00 mensais. O plano Y oferece 20 MB/s por R$ 100,00 mensais. Sabendo que 1 MB/s equivale a 8 Mbps, qual plano oferece maior velocidade e menor custo por Mbps?$text$, $text$Y oferece 20 × 8 = 160 Mbps; seu custo por Mbps é 100/160 = R$ 0,625, inferior a 80/80 = R$ 1,00 do plano X.$text$, 'D', $text$X, com 160 Mbps e custo de R$ 0,50 por Mbps.$text$, $text$X, com 80 Mbps e custo de R$ 0,625 por Mbps.$text$, $text$Os dois têm 80 Mbps e o mesmo custo por Mbps.$text$, $text$Y, com 160 Mbps e custo de R$ 0,625 por Mbps.$text$, $text$Y, com 20 Mbps e custo de R$ 5,00 por Mbps.$text$)
        ) AS seed(code, inspiration_year, exam_area, discipline_name, subject_name,
                  statement, explanation, correct_letter,
                  alternative_a, alternative_b, alternative_c, alternative_d, alternative_e)
    LOOP
        SELECT subject.id INTO STRICT subject_uuid
        FROM subjects subject
        JOIN disciplines discipline ON discipline.id = subject.discipline_id
        WHERE subject.name = item.subject_name
          AND discipline.name = item.discipline_name
          AND discipline.exam_area = item.exam_area;

        INSERT INTO questions (id, statement, explanation, subject_id, active, created_at, updated_at)
        VALUES (gen_random_uuid(), item.statement, item.explanation, subject_uuid, TRUE, CURRENT_TIMESTAMP, NULL)
        RETURNING id INTO question_uuid;

        INSERT INTO alternatives (question_id, letter, text, correct)
        VALUES
            (question_uuid, 'A', item.alternative_a, item.correct_letter = 'A'),
            (question_uuid, 'B', item.alternative_b, item.correct_letter = 'B'),
            (question_uuid, 'C', item.alternative_c, item.correct_letter = 'C'),
            (question_uuid, 'D', item.alternative_d, item.correct_letter = 'D'),
            (question_uuid, 'E', item.alternative_e, item.correct_letter = 'E');

        inserted_count := inserted_count + 1;
    END LOOP;

    IF inserted_count <> 40 THEN
        RAISE EXCEPTION 'Expected 40 new questions, inserted %', inserted_count;
    END IF;
END
$migration$;
